/* LCG PRNG: generates test input i into caller-provided buffer. */
/* Input 0 = test_input_0 (flash). Inputs 1..N-1 generated at runtime. */
static inline void test_generate_input(int idx, int8_t *buf) {
    if (idx == 0) {
        for (int i = 0; i < 76800; i++) buf[i] = test_input_0[i];
        return;
    }
    uint32_t state = TEST_SEED_BASE + (uint32_t)idx * 997U;
    for (int i = 0; i < 76800; i++) {
        state = (state * 1103515245U + 12345U) & 0x7FFFFFFFU;
        buf[i] = (int8_t)((state >> 16) & 0xFF);
    }
}

